    static long[] bitCnt; // soma dos coeficientes angulares (c) cobrindo o ponto
    static long[] bitCst; // soma dos termos constantes (d) cobrindo o ponto
    static byte[] data;
    static int pos;

    // BIT para range update / point query (diferenças + prefix sum)
    static void add(long[] bit, int i, long v) {
        for (; i <= n; i += i & (-i)) bit[i] += v;
    }

    static long pref(long[] bit, int i) {
        long s = 0;
        for (; i > 0; i -= i & (-i)) s += bit[i];
        return s;
    }

    static int nextInt() {
        while (pos < data.length && (data[pos] < '0' || data[pos] > '9') && data[pos] != '-') pos++;
        boolean neg = false;
        if (pos < data.length && data[pos] == '-') { neg = true; pos++; }
        int x = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') {
            x = x * 10 + (data[pos] - '0');
            pos++;
        }
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream(1 << 22);
        byte[] buf = new byte[1 << 16];
        int r;
        while ((r = System.in.read(buf)) != -1) bos.write(buf, 0, r);
        data = bos.toByteArray();
        pos = 0;

