        int m = nextInt();
        bitCnt = new long[n + 1];
        bitCst = new long[n + 1];
        StringBuilder sb = new StringBuilder();

        for (int q = 0; q < m; q++) {
            int type = nextInt();
            if (type == 3) { // IMPRIME
                int x = nextInt();
                long ans = pref(bitCnt, x) * (long) x + pref(bitCst, x);
                sb.append(ans).append('\n');
            } else {
                int i = nextInt();
                int v = nextInt();
                if (type == 1) {
                    // FRENTE: em cada j em [i, min(n, i+v-1)] soma (v+i) - j
                    int rr = (int) Math.min((long) n, (long) i + v - 1);
                    long d = (long) v + i;
                    add(bitCnt, i, -1);
                    add(bitCst, i, d);
                    if (rr < n) {
                        add(bitCnt, rr + 1, 1);
                        add(bitCst, rr + 1, -d);
                    }
                } else {
                    // TRAS: em cada j em [max(1, i-v+1), i] soma j + (v-i)
                    int l = (int) Math.max(1L, (long) i - v + 1);
                    long d = (long) v - i;
                    add(bitCnt, l, 1);
                    add(bitCst, l, d);
                    if (i < n) {
                        add(bitCnt, i + 1, -1);
                        add(bitCst, i + 1, -d);
                    }
                }
            }
        }
        System.out.print(sb);
    }
}
